# P0 vote integrity — one Vote row per (user, legislation, vote_choice).
# Generated by Django 5.2.18 on 2026-10-25 21:42
#
# The guard runs first and deletes NOTHING: if production already holds
# duplicate rows (a double-submitted ballot), the migration stops and names
# them, so a human decides which row is the real ballot instead of a
# migration silently dropping one. CommitteeVote already carries the same
# rule as unique_together (0001_initial).

from django.db import migrations, models
from django.db.models import Count


def _duplicate_ballots(apps):
    Vote = apps.get_model('src', 'Vote')
    return list(
        Vote.objects.values('user_id', 'legislation_id', 'vote_choice')
        .annotate(n=Count('id'))
        .filter(n__gt=1)
        .order_by('legislation_id', 'user_id', 'vote_choice')
    )


def refuse_duplicate_ballots(apps, schema_editor):
    dupes = _duplicate_ballots(apps)
    if not dupes:
        return
    # The choice itself is deliberately NOT printed: on an anonymous vote,
    # user + choice in a deploy log would de-anonymize that ballot (admin
    # confidentiality boundary, v3.16.2). Whoever resolves it looks at the
    # rows for that user and legislation.
    listing = '\n'.join(
        f"  user_id={d['user_id']} legislation_id={d['legislation_id']} "
        f"duplicate_rows={d['n']}"
        for d in dupes
    )
    raise RuntimeError(
        'Cannot add unique_vote_user_legislation_choice: duplicate Vote rows '
        'exist. Resolve them by hand (keep one row per ballot), then re-run '
        'migrate. Nothing was deleted.\n' + listing
    )


